/*
 * Modified by Actuna Sp. z o.o.:
 *   E-01: deployments go through the deploy pipeline (flows/pipeline.js); the deploy
 *   lock moved to flows/lock.js and also serialises setState (POST /flows/state)
 *   P-01: deploy.response "started" - deployments wait for the start of the flows;
 *   deploy_start_failed/deploy_stop_failed (status 500, rev, errors) are passed on
 *   Z-04: single-flow api - flow revision (rev in v2), rev/globalRev checks, globalConfigs,
 *   PUT creating a flow with deploy.putCreatesFlow
 *   Z-05: deploy.requireRevision - 409 version_required (v1 always, DELETE needs rev,
 *   reload exempt); DELETE /flow/:id checks an optional rev; PUT /flow/:id with
 *   globalConfigs needs globalRev
 *   R-45: warnings for deploy.startTimeoutReleasesLock
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

 /**
  * @mixin @node-red/runtime_flows
  */

/**
 * @typedef Flows
 * @type {object}
 * @property {string} rev - the flow revision identifier
 * @property {Array}  flows - the flow configuration, an array of node configuration objects
 */

/**
 * @typedef Flow
 * @type {object}
 * @property {string} id - the flow identifier
 * @property {string} label - a label for the flow
 * @property {Array}  nodes - an array of node configuration objects
 */

var runtime;
// The deploy lock is shared with the project switch (E-01, R-11)
const lock = require("../flows/lock");
const pipeline = require("../flows/pipeline");

const DEPLOY_RESPONSES = ["stopped", "started"];

function getDeploySettings() {
    return (runtime.settings && runtime.settings.deploy) || {};
}

/**
 * The internal deploy options of an Admin API deployment (P-01):
 * `{waitForStart: true}` with `deploy.response: "started"`, otherwise undefined
 * (default behaviour, also for an invalid value - warned about at init).
 * @return {DeployOpts|undefined}
 */
function getDeployOpts() {
    if (getDeploySettings().response === "started") {
        return { waitForStart: true };
    }
    return undefined;
}

function checkDeploySettings() {
    const deploySettings = getDeploySettings();
    if (deploySettings.response !== undefined && DEPLOY_RESPONSES.indexOf(deploySettings.response) === -1) {
        runtime.log.warn(runtime.log._("deploy.invalid-response", {value: String(deploySettings.response)}));
    }
    if (deploySettings.startTimeout !== undefined && !(typeof deploySettings.startTimeout === "number" && deploySettings.startTimeout > 0)) {
        runtime.log.warn(runtime.log._("deploy.invalid-start-timeout", {value: String(deploySettings.startTimeout)}));
    }
    // R-45: releasing the deploy lock after deploy.startTimeout must be enabled explicitly
    if (deploySettings.startTimeoutReleasesLock !== undefined && typeof deploySettings.startTimeoutReleasesLock !== "boolean") {
        runtime.log.warn(runtime.log._("deploy.invalid-start-timeout-releases-lock", {value: String(deploySettings.startTimeoutReleasesLock)}));
    } else if (deploySettings.startTimeoutReleasesLock === true && deploySettings.startTimeout === undefined) {
        runtime.log.warn(runtime.log._("deploy.start-timeout-releases-lock-without-timeout"));
    }
}

// The fields of the single-flow api that are not part of the flow (Z-04)
const SINGLE_FLOW_FIELDS = ["rev", "globalRev", "globalConfigs"];

/**
 * Separates `rev`, `globalRev` and `globalConfigs` from a flow of the single-flow
 * api (Z-04). The flow object is passed on unchanged when it has none of them.
 */
function extractSingleFlowFields(flow) {
    const result = {
        flow: flow,
        rev: { present: false },
        globalRev: { present: false }
    };
    if (!flow || typeof flow !== "object" || Array.isArray(flow) || !SINGLE_FLOW_FIELDS.some(f => flow.hasOwnProperty(f))) {
        return result;
    }
    result.flow = Object.assign({}, flow);
    SINGLE_FLOW_FIELDS.forEach(f => delete result.flow[f]);
    if (flow.hasOwnProperty("rev")) {
        result.rev = { present: true, value: flow.rev };
    }
    if (flow.hasOwnProperty("globalRev")) {
        result.globalRev = { present: true, value: flow.globalRev };
    }
    if (flow.hasOwnProperty("globalConfigs")) {
        result.globalConfigs = flow.globalConfigs;
    }
    return result;
}

// Step 2 for the single-flow api (Z-04): the revision of the flow and of the
// global configuration - under the deploy lock, before the configuration is built
// Z-05: a revision is required for deployments through the Admin API
function isRevisionRequired() {
    return getDeploySettings().requireRevision === true;
}

// options: {requireRev, requireGlobalRev} (Z-05)
function checkSingleFlowRevisions(id, fields, options) {
    options = options || {};
    if (fields.rev.present || options.requireRev) {
        pipeline.checkRevision({
            present: fields.rev.present,
            value: fields.rev.value,
            current: runtime.flows.getFlowRevision(id),
            strictType: true,
            required: !!options.requireRev,
            message: options.requireRev ? runtime.log._("api.flows.version-required") : undefined
        });
    }
    if (fields.globalRev.present || options.requireGlobalRev) {
        pipeline.checkRevision({
            present: fields.globalRev.present,
            value: fields.globalRev.value,
            current: runtime.flows.getFlowRevision("global"),
            strictType: true,
            required: !!options.requireGlobalRev,
            message: options.requireGlobalRev ? runtime.log._("api.flows.version-required") : undefined
        });
    }
}

const REVISION_ERRORS = ["version_mismatch", "version_required", "invalid_revision"];

var api = module.exports = {
    init: function(_runtime) {
        runtime = _runtime;
        pipeline.init(runtime);
        checkDeploySettings();
    },
    /**
    * Gets the current flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<Flows>} - the active flow configuration
    * @memberof @node-red/runtime_flows
    */
    getFlows: async function(opts) {
        runtime.log.audit({event: "flows.get"}, opts.req);
        return runtime.flows.getFlows();
    },
    /**
    * Sets the current flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.flows - the flow configuration: `{flows: [..], credentials: {}}`
    * @param {Object} opts.deploymentType - the type of deployment - "full", "nodes", "flows", "reload"
    * @param {String} [opts.apiVersion] - "v1" | "v2" of the Admin API request: with
    *     `deploy.requireRevision: true` a v1 deployment (no place for `rev`) is rejected with
    *     409 `version_required`; a v2 deployment without `rev` too (Z-05). `reload` is exempt
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<Flows>} - the active flow configuration
    *
    * With `deploy.response: "started"` (P-01) the promise resolves after the new flows
    * have started. Errors of such a deployment (the configuration is saved):
    * `{code: "deploy_start_failed", status: 500, message, rev, errors: [{code, message, ...}]}`
    * with `errors[].code` "missing_types" | "missing_modules" | "flow_start_failed" |
    * "safe_mode" | "start_timeout" (`deploy.startTimeout`), and
    * `{code: "deploy_stop_failed", status: 500, message, rev}`. The same applies to
    * addFlow, updateFlow and deleteFlow.
    * @memberof @node-red/runtime_flows
    */
    setFlows: async function(opts) {
        var flows = opts.flows;
        var deploymentType = opts.deploymentType||"full";
        runtime.log.audit({event: "flows.set",type:deploymentType}, opts.req);
        return pipeline.deploy({
            type: deploymentType,
            source: "api",
            flows: flows,
            user: opts.user,
            req: opts.req,
            deployOpts: getDeployOpts(),
            requireRevision: isRevisionRequired(),
            apiVersion: opts.apiVersion
        }).then(function(result) {
            return {rev:result.rev};
        }).catch(function(err) {
            if (err.code === "version_required" || err.code === "invalid_revision") {
                runtime.log.audit({event: "flows.set", type: deploymentType, error: err.code}, opts.req);
            }
            if (REVISION_ERRORS.indexOf(err.code) === -1) {
                //TODO: log warning for version_mismatch
                runtime.log.warn(runtime.log._("api.flows.error-"+(deploymentType === 'reload'?'reload':'save'),{message:err.message}));
                runtime.log.warn(err.stack);
            }
            throw err
        });
    },

    /**
    * Adds a flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.flow - the flow to add; optionally (Z-04) `globalConfigs` -
    *     global configuration nodes to add or replace - and `globalRev` - the revision
    *     of the global configuration (409 `version_mismatch` if it differs)
    * @param {String} [opts.apiVersion] - "v1" (default) or "v2"
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<String|{id: String, rev: String}>} - the id of the added flow;
    *     with apiVersion "v2" `{id, rev}` (Z-04)
    * @memberof @node-red/runtime_flows
    */
    addFlow: async function(opts) {
        var fields = extractSingleFlowFields(opts.flow);
        var flow = fields.flow;
        return pipeline.deploy({
            type: "flows",
            source: "api",
            user: opts.user,
            req: opts.req,
            deployOpts: getDeployOpts(),
            apply: function(deployOpts) {
                // rev of a new flow is not checked (ignored, as before); with
                // requireRevision globalConfigs need globalRev (Z-05)
                checkSingleFlowRevisions(null, {rev: {present: false}, globalRev: fields.globalRev}, {
                    requireGlobalRev: isRevisionRequired() && fields.globalConfigs !== undefined
                });
                if (fields.globalConfigs !== undefined) {
                    return runtime.flows.addFlow(flow, opts.user, deployOpts, {globalConfigs: fields.globalConfigs});
                }
                return runtime.flows.addFlow(flow, opts.user, deployOpts);
            }
        }).then(function (result) {
            var id = result.result;
            var auditEvent = {event: "flow.add", id: id};
            if (Array.isArray(fields.globalConfigs)) {
                auditEvent.globalConfigs = fields.globalConfigs.map(n => n && n.id);
            }
            runtime.log.audit(auditEvent, opts.req);
            if (opts.apiVersion === "v2") {
                return {id: id, rev: runtime.flows.getFlowRevision(id)};
            }
            return id;
        }).catch(function (err) {
            runtime.log.audit({
                event: "flow.add",
                error: err.code || "unexpected_error",
                message: err.toString()
            }, opts.req);
            // P-01: deploy_start_failed/deploy_stop_failed keep status 500;
            // Z-04: version_mismatch 409
            err.status = err.status || 400;
            throw err;
        });
    },

    /**
    * Gets an individual flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.id - the id of the flow to retrieve
    * @param {String} [opts.apiVersion] - "v1" (default) or "v2": with "v2" the result
    *     includes `rev` - the revision of the flow (Z-04)
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<Flow>} - the active flow configuration
    * @memberof @node-red/runtime_flows
    */
    getFlow: async function(opts) {
        var flow = runtime.flows.getFlow(opts.id);
        if (flow) {
            runtime.log.audit({event: "flow.get",id:opts.id}, opts.req);
            if (opts.apiVersion === "v2") {
                return Object.assign({}, flow, {rev: runtime.flows.getFlowRevision(opts.id)});
            }
            return flow;
        } else {
            runtime.log.audit({event: "flow.get",id:opts.id,error:"not_found"}, opts.req);
            var err = new Error();
            err.code = "not_found";
            err.status = 404;
            throw err;
        }
    },
    /**
    * Updates an existing flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.id - the id of the flow to update
    * @param {Object} opts.flow - the flow configuration; optionally (Z-04) `rev` - the
    *     revision of the flow (`null`: the flow must not exist), `globalConfigs` and
    *     `globalRev` (as for addFlow). A revision that differs: 409 `version_mismatch`;
    *     not a string: 400 `invalid_revision`
    * @param {String} [opts.apiVersion] - "v1" (default) or "v2"
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<String|{id: String, rev: String, revAll: String, created: boolean}>} -
    *     the id of the updated flow; with apiVersion "v2" also the new revision of the flow,
    *     of the whole configuration and whether the flow was created (Z-04).
    *     With `deploy.putCreatesFlow: true` a flow that does not exist is created under `id`.
    * @memberof @node-red/runtime_flows
    */
    updateFlow: async function(opts) {
        var fields = extractSingleFlowFields(opts.flow);
        var flow = fields.flow;
        var id = opts.id;
        var putCreatesFlow = getDeploySettings().putCreatesFlow === true;
        return pipeline.deploy({
            type: "flows",
            source: "api",
            user: opts.user,
            req: opts.req,
            deployOpts: getDeployOpts(),
            apply: function(deployOpts) {
                // Z-05: a missing flow without putCreatesFlow stays 404 (not version_required)
                var requireRev = isRevisionRequired() && (putCreatesFlow || id === "global" || runtime.flows.getFlowRevision(id) !== null);
                // with requireRevision globalConfigs need globalRev, as for addFlow (Z-05)
                checkSingleFlowRevisions(id, fields, {
                    requireRev: requireRev,
                    requireGlobalRev: isRevisionRequired() && fields.globalConfigs !== undefined
                });
                if (putCreatesFlow || fields.globalConfigs !== undefined) {
                    var updateOpts = {};
                    if (putCreatesFlow) {
                        updateOpts.create = true;
                    }
                    if (fields.globalConfigs !== undefined) {
                        updateOpts.globalConfigs = fields.globalConfigs;
                    }
                    return runtime.flows.updateFlow(id, flow, opts.user, deployOpts, updateOpts);
                }
                return runtime.flows.updateFlow(id, flow, opts.user, deployOpts);
            }
        }).then(function (result) {
            var created = !!(result && result.result && result.result.created);
            var auditEvent = {event: "flow.update", id: id};
            if (created) {
                auditEvent.created = true;
            }
            if (Array.isArray(fields.globalConfigs)) {
                auditEvent.globalConfigs = fields.globalConfigs.map(n => n && n.id);
            }
            runtime.log.audit(auditEvent, opts.req);
            if (opts.apiVersion === "v2") {
                return {id: id, rev: runtime.flows.getFlowRevision(id), revAll: runtime.flows.getFlows().rev, created: created};
            }
            return id;
        }).catch(function (err) {
            if (err.code === 404) {
                runtime.log.audit({event: "flow.update", id: id, error: "not_found"}, opts.req);
                // TODO: this swap around of .code and .status isn't ideal
                err.status = 404;
                err.code = "not_found";
            } else {
                runtime.log.audit({
                    event: "flow.update",
                    error: err.code || "unexpected_error",
                    message: err.toString()
                }, opts.req);
                // P-01: deploy_start_failed/deploy_stop_failed keep status 500;
                // Z-04: version_mismatch 409
                err.status = err.status || 400;
            }
            throw err;
        });
    },
    /**
    * Deletes a flow
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.id - the id of the flow to delete
    * @param {String} [opts.rev] - the revision of the flow (Z-05): checked when given
    *     (409 `version_mismatch`), required with `deploy.requireRevision: true`
    *     (409 `version_required`)
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise} - resolves if successful
    * @memberof @node-red/runtime_flows
    */
    deleteFlow: async function(opts) {
        var id = opts.id;
        return pipeline.deploy({
            type: "flows",
            source: "api",
            user: opts.user,
            req: opts.req,
            deployOpts: getDeployOpts(),
            apply: function(deployOpts) {
                // Z-05 (R-14): ?rev= - checked when given, required with requireRevision
                var revPresent = opts.rev !== undefined;
                var requireRev = isRevisionRequired() && runtime.flows.getFlowRevision(id) !== null;
                checkSingleFlowRevisions(id, {rev: {present: revPresent, value: opts.rev}, globalRev: {present: false}}, {requireRev: requireRev});
                return runtime.flows.removeFlow(id, opts.user, deployOpts);
            }
        }).then(function () {
            runtime.log.audit({event: "flow.remove", id: id}, opts.req);
            return;
        }).catch(function (err) {
            if (err.code === 404) {
                runtime.log.audit({event: "flow.remove", id: id, error: "not_found"}, opts.req);
                // TODO: this swap around of .code and .status isn't ideal
                err.status = 404;
                err.code = "not_found";
            } else {
                runtime.log.audit({
                    event: "flow.remove",
                    id: id,
                    error: err.code || "unexpected_error",
                    message: err.toString()
                }, opts.req);
                // P-01: deploy_start_failed/deploy_stop_failed keep status 500
                err.status = err.status || 400;
            }
            throw err;
        });
    },

    /**
    * Gets the safe credentials for a node
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {String} opts.type - the node type to return the credential information for
    * @param {String} opts.id - the node id
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<Object>} - the safe credentials
    * @memberof @node-red/runtime_flows
    */
    getNodeCredentials: async function(opts) {
        runtime.log.audit({event: "credentials.get",type:opts.type,id:opts.id}, opts.req);
        var credentials = runtime.nodes.getCredentials(opts.id);
        if (!credentials) {
            return {};
        }
        var sendCredentials = {};
        var cred;
        if (/^subflow(:|$)/.test(opts.type) ||
            (opts.type === "tab") ||
            (opts.type === "group")) {
            for (cred in credentials) {
                if (credentials.hasOwnProperty(cred)) {
                    sendCredentials['has_'+cred] = credentials[cred] != null && credentials[cred] !== '';
                }
            }
        } else {
            var definition = runtime.nodes.getCredentialDefinition(opts.type) || {};
            for (cred in definition) {
                if (definition.hasOwnProperty(cred)) {
                    if (definition[cred].type == "password") {
                        var key = 'has_' + cred;
                        sendCredentials[key] = credentials[cred] != null && credentials[cred] !== '';
                        continue;
                    }
                    sendCredentials[cred] = credentials[cred] || '';
                }
            }
        }
        return sendCredentials;
    },
    /**
    * Gets running state of runtime flows
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.req - the request to log (optional)
    * @return {{state:string, started:boolean}} - the current run state of the flows
    * @memberof @node-red/runtime_flows
    */
    getState: async function(opts) {
        runtime.log.audit({event: "flows.getState"}, opts.req);
        const result = {
            state: runtime.flows.state()
        }
        return result;
    },
    /**
    * Sets running state of runtime flows
    * @param {Object} opts
    * @param {Object} opts.req - the request to log (optional)
    * @param {User} opts.user - the user calling the api
    * @param {string} opts.state - the requested state. Valid values are "start" and "stop".
    * @return {Promise<Flow>} - the active flow configuration
    * @memberof @node-red/runtime_flows
    */
    setState: async function(opts) {
        opts = opts || {};
        const makeError = (error, errcode, statusCode) => {
            const message = typeof error == "object" ? error.message : error
            const err = typeof error == "object" ? error : new Error(message||"Unexpected Error")
            err.status = err.status || statusCode || 400;
            err.code = err.code || errcode || "unexpected_error"
            runtime.log.audit({
                event: "flows.setState",
                state: opts.state || "",
                error: errcode || "unexpected_error",
                message: err.code
            }, opts.req);
            return err
        }

        const getState = () => {
            return {
                state: runtime.flows.state()
            }
        }

        if(!runtime.settings.runtimeState || runtime.settings.runtimeState.enabled !== true) {
            throw (makeError("Method Not Allowed", "not_allowed", 405))
        }
        // Serialised with deployments and project switches: waits for a
        // running operation to complete (E-01, R-11); no hooks (R-15)
        return lock.runExclusive(async function() {
            switch (opts.state) {
                case "start":
                    try {
                        try {
                            runtime.settings.set('runtimeFlowState', opts.state);
                        } catch(err) {}
                        if (runtime.settings.safeMode) {
                            delete runtime.settings.safeMode
                        }
                        await runtime.flows.startFlows("full")
                        return getState()
                    } catch (err) {
                        throw (makeError(err, err.code, 500))
                    }
                case "stop":
                    try {
                        try {
                            runtime.settings.set('runtimeFlowState', opts.state);
                        } catch(err) {}
                        await runtime.flows.stopFlows("full")
                        return getState()
                    } catch (err) {
                        throw (makeError(err, err.code, 500))
                    }
                default:
                    throw (makeError(`Cannot change flows runtime state to '${opts.state}'}`, "invalid_run_state", 400))
            }
        });
    },
}
